import pickle
import json

class SessionCache:
    def __init__(self):
        self.cache = {}

    def set_session(self, session_id, session_data):
        """Store session data as pickle for fast serialization."""
        self.cache[session_id] = pickle.dumps(session_data)

    def get_session(self, session_id):
        """Retrieve and deserialize session data by ID."""
        if session_id in self.cache:
            return pickle.loads(self.cache[session_id])
        return None

    def clear_session(self, session_id):
        if session_id in self.cache:
            del self.cache[session_id]

# Usage
cache = SessionCache()
cache.set_session('user_123', {'username': 'alice', 'role': 'admin', 'login_time': 1234567890})
session = cache.get_session('user_123')
print(session)
